CREATE TABLE headcount_budgets (id TEXT PRIMARY KEY,department_id TEXT NOT NULL REFERENCES departments(id),budget_year INTEGER NOT NULL CHECK(budget_year BETWEEN 1000 AND 9999),current_version_id TEXT,UNIQUE(department_id,budget_year));
CREATE TABLE headcount_budget_versions (id TEXT PRIMARY KEY,budget_id TEXT NOT NULL REFERENCES headcount_budgets(id),version_number INTEGER NOT NULL CHECK(version_number>0),approved_headcount INTEGER NOT NULL CHECK(approved_headcount>=0),annual_salary_budget NUMERIC NOT NULL CHECK(annual_salary_budget>=0),actor_id TEXT NOT NULL,actor_name TEXT NOT NULL,reason TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(budget_id,version_number));
ALTER TABLE headcount_budgets ADD CONSTRAINT headcount_current_version FOREIGN KEY(current_version_id) REFERENCES headcount_budget_versions(id) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE headcount_budget_participation (requisition_id TEXT PRIMARY KEY REFERENCES requisitions(id),approved BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE headcount_budget_reservations (requisition_id TEXT PRIMARY KEY REFERENCES requisitions(id),department_id TEXT NOT NULL REFERENCES departments(id),budget_year INTEGER NOT NULL,headcount_delta INTEGER NOT NULL CHECK(headcount_delta>=0),salary_delta NUMERIC NOT NULL CHECK(salary_delta>=0),replaces_unapproved BOOLEAN NOT NULL DEFAULT FALSE,content_hash TEXT NOT NULL,submission_id TEXT NOT NULL REFERENCES requisition_approval_submissions(id),created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX headcount_reservation_budget ON headcount_budget_reservations(department_id,budget_year);
CREATE TABLE headcount_budget_exceptions (id TEXT PRIMARY KEY,requisition_id TEXT NOT NULL REFERENCES requisitions(id),department_id TEXT NOT NULL REFERENCES departments(id),budget_year INTEGER NOT NULL,version_id TEXT NOT NULL REFERENCES headcount_budget_versions(id),content_hash TEXT NOT NULL,headcount_over INTEGER NOT NULL CHECK(headcount_over>=0),salary_over NUMERIC NOT NULL CHECK(salary_over>=0),confirmed_by TEXT NOT NULL,confirmed_name TEXT NOT NULL,reason TEXT NOT NULL CHECK(length(trim(reason))>0),created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX headcount_exception_lookup ON headcount_budget_exceptions(requisition_id,content_hash,version_id);
CREATE FUNCTION headcount_history_guard() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'BUDGET_HISTORY_IMMUTABLE'; END; $$;
CREATE TRIGGER headcount_budget_versions_immutable BEFORE UPDATE OR DELETE ON headcount_budget_versions FOR EACH ROW EXECUTE FUNCTION headcount_history_guard();
CREATE TRIGGER headcount_budget_versions_no_truncate BEFORE TRUNCATE ON headcount_budget_versions FOR EACH STATEMENT EXECUTE FUNCTION headcount_history_guard();
CREATE TRIGGER headcount_budget_exceptions_immutable BEFORE UPDATE OR DELETE ON headcount_budget_exceptions FOR EACH ROW EXECUTE FUNCTION headcount_history_guard();
CREATE TRIGGER headcount_budget_exceptions_no_truncate BEFORE TRUNCATE ON headcount_budget_exceptions FOR EACH STATEMENT EXECUTE FUNCTION headcount_history_guard();
